export function dinoSvg(name: string): string {
  const a = DINO_ART[name];
  if (!a) return "";
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${a.viewBox}" role="img" aria-label="${name}" preserveAspectRatio="xMidYMid meet">${a.inner}</svg>`;
}
